/**
 * Spatial DPP v0.1.0 — TypeScript type surface for the WASM bindings.
 *
 * Mirrors schemas/v0.1.0/spatial-dpp.schema.json (canonical field names).
 * `pkg/` is generated by `wasm-pack build`; this file documents the API and
 * doubles as the type reference for hand-typed consumers.
 */

// ---------------------------------------------------------------------------
// Validation report
// ---------------------------------------------------------------------------

export interface ValidationIssue {
  /** Rule id from SPEC.md Section 6, e.g. "V-02" or "W-03". */
  code: string;
  /** JSON Pointer into the document, e.g. "/objects/0/physical/mass_kg". */
  path: string;
  message: string;
}

export interface ValidationReport {
  valid: boolean;
  errors: ValidationIssue[];
  warnings: ValidationIssue[];
  document_id?: string | null;
  object_count: number;
}

// ---------------------------------------------------------------------------
// Data model (JSON field names)
// ---------------------------------------------------------------------------

export type GeometryFormat = "gltf" | "usda" | "usdc" | "step" | "obj" | "stl";
export type HashAlgorithm = "sha256" | "sha512";
export type JointType = "revolute" | "prismatic" | "fixed" | "spherical";
export type DisassemblyAction =
  | "unfasten"
  | "cut"
  | "lift"
  | "release"
  | "drain"
  | "deactivate"
  | "other";
export type Hazard =
  | "none"
  | "thermal_runaway"
  | "chemical"
  | "asbestos"
  | "electrical"
  | "sharp"
  | "crush";
export type CraConformance = "conformant" | "partial" | "unknown";

export interface SpatialDppDocument {
  metadata: DocumentMetadata;
  objects: SpatialObject[];
}

export interface DocumentMetadata {
  spec_version: "0.1.0";
  document_id: string;
  name: string;
  created: string;
  author?: string;
  language?: string;
}

export interface SpatialObject {
  id: string;
  label: string;
  geometry: GeometryRef;
  physical: PhysicalProperties;
  compliance: ComplianceRecord;
}

export interface GeometryRef {
  format: GeometryFormat;
  uri: string;
  hash?: ContentHash;
  locator?: string;
  scale_hint_m?: number[];
}

export interface ContentHash {
  algorithm: HashAlgorithm;
  value: string;
}

export interface PhysicalProperties {
  mass_kg: number;
  center_of_mass: [number, number, number];
  density_kg_m3?: number;
  friction: FrictionModel;
  stiffness: Stiffness;
  joints?: KinematicJoint[];
}

export interface FrictionModel {
  static: number;
  kinetic?: number;
}

export interface Stiffness {
  youngs_modulus_pa: number;
  shear_modulus_pa?: number;
  poisson_ratio?: number;
}

export interface KinematicJoint {
  id: string;
  type: JointType;
  axis?: [number, number, number];
  limits?: JointLimits;
  parent: string;
  child: string;
}

export interface JointLimits {
  lower_deg?: number;
  upper_deg?: number;
  lower_m?: number;
  upper_m?: number;
}

export interface ComplianceRecord {
  bill_of_materials: BomEntry[];
  material_composition: MaterialFraction[];
  recyclability_rate: number;
  dpp: DppRecord;
  disassembly?: DisassemblyPlan;
  cra: CraRecord;
}

export interface BomEntry {
  part_id: string;
  label: string;
  quantity: number;
  material_id?: string;
  mass_kg?: number;
}

export interface MaterialFraction {
  material_id: string;
  label: string;
  fraction: number;
}

export interface DppRecord {
  passport_id: string;
  sbom_ref?: string;
  hbom_ref?: string;
  repairability_score?: number;
}

export interface DisassemblyPlan {
  plan_ref?: string;
  steps?: DisassemblyStep[];
}

export interface DisassemblyStep {
  order: number;
  action: DisassemblyAction;
  target: string;
  tool?: string;
  hazard?: Hazard;
  note?: string;
}

export interface CraRecord {
  conformance: CraConformance;
  support_period_until?: string;
  vulnerability_disclosure_uri?: string;
  logs?: CraLogEntry[];
}

export interface CraLogEntry {
  timestamp: string;
  event: string;
  detail?: string;
}

// ---------------------------------------------------------------------------
// WASM exports (names as generated by wasm-bindgen)
// ---------------------------------------------------------------------------

export declare function version(): string;

/** Validate a JSON/JSON-LD document; returns the report as a JSON string. */
export declare function validate_json(src: string): string;

/** Human-readable summary (the `spatial-dpp inspect` output). */
export declare function inspect_json(src: string): string;

/** JSON → JSON-LD (adds @context/@type). */
export declare function to_jsonld(src: string): string;

/** JSON → MessagePack bytes. */
export declare function to_msgpack(src: string): Uint8Array;

/** MessagePack bytes → canonical JSON. */
export declare function from_msgpack(bytes: Uint8Array): string;

/** JSON → Protobuf bytes. */
export declare function to_protobuf(src: string): Uint8Array;

/** Protobuf bytes → canonical JSON. */
export declare function from_protobuf(bytes: Uint8Array): string;
